package vn.edu.eaut.lab7.filter;import jakarta.servlet.*;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;@WebFilter("/admin/*")public class LoginFilter implements Filter{public void doFilter(ServletRequest q,ServletResponse s,FilterChain c)throws IOException,ServletException{HttpServletRequest r=(HttpServletRequest)q;HttpServletResponse p=(HttpServletResponse)s;HttpSession x=r.getSession(false);if(x==null||x.getAttribute("username")==null){p.sendRedirect(r.getContextPath()+"/login.jsp");return;}c.doFilter(q,s);}}
